-- Apply to the world database in MySQL batch mode.
-- -1 is unrestricted; 255 is the eight playable races in WoW 1.12.
CREATE TEMPORARY TABLE _quest_race_candidates (entry INT UNSIGNED PRIMARY KEY, old_race INT NOT NULL, old_class INT NOT NULL, old_bonding INT NOT NULL);
CREATE TEMPORARY TABLE _quest_race_guard (id INT PRIMARY KEY);
LOCK TABLES item_template WRITE;
-- Abort before the update if any candidate is missing or no longer matches the snapshot.
UPDATE item_template JOIN _quest_race_candidates ON item_template.entry=_quest_race_candidates.entry SET item_template.AllowableRace=-1 WHERE item_template.AllowableRace=_quest_race_candidates.old_race AND item_template.class=_quest_race_candidates.old_class AND item_template.bonding=_quest_race_candidates.old_bonding;
SELECT ROW_COUNT() AS changed_rows;
UNLOCK TABLES;
DROP TEMPORARY TABLE _quest_race_guard, _quest_race_candidates;
